<?php declare(strict_types=1);$reportValues=$reportUi['edit_values'];$reportBlocked=$reportUi['blocked'];?>
<?php if(!$reportUi['posted']):?><a class="btn btn-outline theme-secondary" href="<?=e($reportUrl(['report_id'=>$reportValues['report_id']]))?>"><?=e($reportText('Bearbeitung abbrechen und gespeicherten Bericht öffnen'))?></a><?php endif?>
<?php if($reportUi['posted']):?><section class="card"><p><?=e($reportText($reportBlocked?'Die Speicherung wurde nicht bestätigt. Dein Text bleibt erhalten; vergleiche ihn mit dem gespeicherten Bericht.':'Bitte den markierten Berichtstext prüfen und erneut speichern.'))?></p><?php try{$reportCurrentComparison=$reports->get($reportValues['report_id']);}catch(\DomainException){$reportCurrentComparison=null;}if($reportCurrentComparison!==null):?><details class="card" data-activity-report-current-comparison><summary><?=e($reportText('Aktuell gespeicherten Bericht vergleichen'))?></summary><article class="report-body"><?=nl2br(e($reportCurrentComparison['body']))?></article><p><a class="btn btn-outline theme-secondary" href="<?=e($reportUrl(['report_id'=>$reportValues['report_id']]))?>"><?=e($reportText('Gespeicherten Bericht öffnen'))?></a></p></details><?php endif?><?php if($reportBlocked):?><label><?=e($reportText('Dein noch nicht gespeicherter Berichtstext'))?><textarea class="form-control" readonly rows="12" data-activity-report-copy><?=(str_starts_with($reportValues['body'],"\n")||str_starts_with($reportValues['body'],"\r")?"\n":'').e($reportValues['body'])?></textarea></label><?php endif?></section><?php endif?>
<?php if(!$reportUi['posted']):?><h2><?=e($reportUi['selected']['from_year'].($reportUi['selected']['from_year']!==$reportUi['selected']['to_year']?' - '.$reportUi['selected']['to_year']:''))?></h2><?php endif?>
<fieldset <?=$reportBlocked?'disabled':''?>><form method="post" action="<?=e($reportUrl(['report_id'=>$reportValues['report_id'],'edit'=>'1']))?>" class="card" data-activity-report-edit <?=$reportBlocked?'data-activity-report-readonly':''?>><?=csrf().hidden('action','activity-report-edit').hidden('report_kind',$reportKind).hidden('report_id',$reportValues['report_id']).hidden('version',$reportValues['version']).hidden('source_hash',$reportValues['source_hash'])?><label><?=e($reportText('Bericht bearbeiten'))?><textarea class="form-control" name="body" rows="18" maxlength="40000" required><?=(str_starts_with($reportValues['body'],"\n")||str_starts_with($reportValues['body'],"\r")?"\n":'').e($reportValues['body'])?></textarea></label><p><?=e($reportText('Eine Änderung erfordert eine erneute persönliche PDF-Prüfung und Freigabe.'))?></p><button class="btn btn-solid theme-primary"><?=e($reportText('Änderungen speichern'))?></button></form></fieldset>
<?php if($reportBlocked&&http_response_code()===503):require __DIR__.'/retry.php';endif?>
